export const PRIOSDK_PHYSICS_MODULE_VERSION = 1;

let initializationPromise: Promise<typeof RAPIER> | undefined;

export const createRapierModule = (): Promise<typeof RAPIER> => {
  if (initializationPromise !== undefined) return initializationPromise;
  initializationPromise = initRapier()
    .then(() => RAPIER)
    .catch((error: unknown) => {
      initializationPromise = undefined;
      throw error;
    });
  return initializationPromise;
};
